import { test, expect } from '@playwright/test';

test.describe('File Upload Progress Bar', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display progress bar for each file being uploaded', async ({ page }) => {
    // Intercept the API call to get file upload status
    await page.route('**/api/upload/status', (route) => {
      route.continue();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select a file using getByLabel
    const fileSelect = page.getByLabel(/select file/i);
    await fileSelect.setInputFiles('fixtures/sample-file.pdf');

    // Verify progress bar is visible
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify progress bar has a value
    const progressValue = page.getByText(/100%/i);
    await expect(progressValue).toBeVisible();

    // Verify progress bar is styled correctly
    await expect(progressBar).toHaveClass(/progress-bar/i);

    // Verify upload status is displayed
    const uploadStatus = page.getByText(/uploading/i);
    await expect(uploadStatus).toBeVisible();

    // Verify progress bar updates as file uploads
    await page.waitForTimeout(100);
    const updatedProgressValue = page.getByText(/50%/i);
    await expect(updatedProgressValue).toBeVisible();

    // Verify progress bar reaches 100%
    const finalProgressValue = page.getByText(/100%/i);
    await expect(finalProgressValue).toBeVisible();

    // Verify success message is displayed
    const successMessage = page.getByText(/file uploaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify file name is displayed
    const fileName = page.getByText(/sample-file.pdf/i);
    await expect(fileName).toBeVisible();

    // Verify file preview is displayed
    const filePreview = page.getByRole('img', { name: /sample-file.pdf/i });
    await expect(filePreview).toBeVisible();

    // Verify file upload button is disabled after upload
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeDisabled();
  });

  test('should handle multiple file uploads with individual progress bars', async ({ page }) => {
    // Intercept the API call to get file upload status
    await page.route('**/api/upload/status', (route) => {
      route.continue();
    });

    // Locate and click the file input using getByRole
    const fileInput = page.getByRole('button', { name: /choose file/i });
    await fileInput.click();

    // Locate and select multiple files using getByLabel
    const fileSelect = page.getByLabel(/select file/i);
    await fileSelect.setInputFiles('fixtures/sample-file1.pdf', 'fixtures/sample-file2.pdf');

    // Verify multiple progress bars are visible
    const progressBar1 = page.getByRole('progressbar');
    await expect(progressBar1).toBeVisible();
    const progressBar2 = page.getByRole('progressbar');
    await expect(progressBar2).toBeVisible();

    // Verify each progress bar has a value
    const progressValue1 = page.getByText(/100%/i);
    await expect(progressValue1).toBeVisible();
    const progressValue2 = page.getByText(/100%/i);
    await expect(progressValue2).toBeVisible();

    // Verify progress bars are styled correctly
    await expect(progressBar1).toHaveClass(/progress-bar/i);
    await expect(progressBar2).toHaveClass(/progress-bar/i);

    // Verify upload status is displayed for each file
    const uploadStatus1 = page.getByText(/uploading/i);
    await expect(uploadStatus1).toBeVisible();
    const uploadStatus2 = page.getByText(/uploading/i);
    await expect(uploadStatus2).toBeVisible();

    // Verify success message is displayed for each file
    const successMessage1 = page.getByText(/file 1 uploaded successfully/i);
    await expect(successMessage1).toBeVisible();
    const successMessage2 = page.getByText(/file 2 uploaded successfully/i);
    await expect(successMessage2).toBeVisible();

    // Verify file names are displayed for each file
    const fileName1 = page.getByText(/sample-file1.pdf/i);
    await expect(fileName1).toBeVisible();
    const fileName2 = page.getByText(/sample-file2.pdf/i);
    await expect(fileName2).toBeVisible();

    // Verify file preview is displayed for each file
    const filePreview1 = page.getByRole('img', { name: /sample-file1.pdf/i });
    await expect(filePreview1).toBeVisible();
    const filePreview2 = page.getByRole('img', { name: /sample-file2.pdf/i });
    await expect(filePreview2).toBeVisible();

    // Verify file upload button is disabled after upload
    const uploadButton = page.getByRole('button', { name: /upload file/i });
    await expect(uploadButton).toBeDisabled();
  });
});
